#include <stdio.h>

int root(int n) {
    while (n > 9) {
        int s = 0;
        while (n != 0) {
            s = s + n % 10;
            n = n / 10;
        }
        n = s;
    }
    return n;
}

int main() {
    printf("%d\n", root(9875));
    printf("%d\n", root(6789));
    return 0;
}

solution.code:
#include <stdio.h>

int root(int n) {
    return n == 0 ? 0 : 1 + (n - 1) % 9;
}

int main() {
    printf("%d\n", root(9875));
    printf("%d\n", root(6789));
    return 0;
}
